using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: discriminator property renamed from "Discriminator" to "$type".
        // Revert to EF8 name so existing 500K documents remain readable without migration.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 breaking change: id format changed from "EntityType|Key" to just "Key".
        // Preserve EF8 id format so existing documents (e.g. "Product|123") are still found.
        modelBuilder.Entity<Product>().HasIdProperty(p => p.Id)
            .HasIdValueGeneratorFactory((p, t) =>
                new Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.Internal
                    .IdValueGenerator());

        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}
