using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1: Discriminator property renamed "$type" in EF9.
            // Revert to "Discriminator" so existing 500K docs stay readable and
            // raw SQL queries (WHERE c.Discriminator = 'Product') keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2: id values no longer prefixed with "EntityType|".
            // EF8 stored "Product|123"; EF9 stores just "123".
            // Use a shadow __id property with a value converter to keep the old format.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasConversion(
                      v => v,
                      v => v);
            entity.HasKey("__id");
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // BREAKING CHANGE 3: Sync I/O throws by default in EF9 Cosmos provider.
        // Either use async APIs everywhere (preferred) or opt back in:
        // options.UseCosmos(...).EnableSyncApiSupport();
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

